#!/usr/bin/env sage
"""jac26_debug_v1.sage -- diagnose (i) the lambda-coordinate at P = -R, and (ii) why the
even-n control tripped the chisum == S_rat - S_conj instrument check.  Diagnosis only."""


# This file was *autogenerated* from the file jac26_debug_v1.sage
from sage.all_cmdline import *   # import sage library

_sage_const_4 = Integer(4); _sage_const_6 = Integer(6); _sage_const_2 = Integer(2); _sage_const_8 = Integer(8); _sage_const_3 = Integer(3); _sage_const_0 = Integer(0); _sage_const_1 = Integer(1); _sage_const_43 = Integer(43); _sage_const_7 = Integer(7); _sage_const_67 = Integer(67); _sage_const_5 = Integer(5); _sage_const_79 = Integer(79)
from sage.all import GF, EllipticCurve, ZZ, PolynomialRing, Integer


def DF(A, B, xR, yR, ring):
    l = ring.gen()
    return (l**_sage_const_4  - _sage_const_6 *xR*l**_sage_const_2  - _sage_const_8 *yR*l - (_sage_const_3 *xR**_sage_const_2  + _sage_const_4 *A),
            yR*l**_sage_const_3  + (A + _sage_const_3 *xR**_sage_const_2 )*l**_sage_const_2  + _sage_const_3 *xR*yR*l + yR**_sage_const_2 )


def diagnose(p, A, B, e):
    K = GF(p)
    E = EllipticCurve(K, [A, B])
    n = E.order()
    Gen = E.gens()[_sage_const_0 ]
    Rpt = Integer(e)*Gen
    xR, yR = K(Rpt[_sage_const_0 ]), K(Rpt[_sage_const_1 ])
    if yR == _sage_const_0 :
        print("  R is 2-torsion, skip")
        return
    Kl = PolynomialRing(K, 'l')
    D, F = DF(K(A), K(B), xR, yR, Kl)
    G = D*F
    print("p=%d A=%d B=%d n=%d (%s) e=%d R=(%s,%s) | ord(R)=%d | deg G=%d sqfree=%s"
          % (p, A, B, n, "odd" if n % _sage_const_2  else "EVEN", e, xR, yR, Rpt.order(),
             G.degree(), G.is_squarefree()))

    # how many rational halves does R have?  (= rational roots of D)
    halves = [P for P in E.points() if _sage_const_2 *P == Rpt]
    print("   rational P with 2P=R: %d   | rational roots of D: %d   | rational roots of F: %d"
          % (len(halves), len(D.roots()), len(F.roots())))
    print("   rational 2-torsion pts (y=0): %d" % len([P for P in E.points()
                                                       if not P.is_zero() and P[_sage_const_1 ] == _sage_const_0 ]))

    # build the lambda <-> pair correspondence EXPLICITLY and audit every lambda in F_p
    # lam(P) = slope of the line through P, R-P, -R.
    lam2pair = {}
    for P in E.points():
        if P.is_zero():
            continue
        P2 = Rpt - P
        if P2.is_zero():
            continue                    # the pair {O,R} -> lambda = infinity
        if P[_sage_const_0 ] == xR:
            # P = -R  (P = R is excluded above since then P2 = O): tangent at -R
            lam = -(_sage_const_3 *xR**_sage_const_2  + K(A))/(_sage_const_2 *yR)
        else:
            lam = (P[_sage_const_1 ] + yR)/(P[_sage_const_0 ] - xR)
        lam2pair.setdefault(lam, set()).add(tuple(P))

    bad = _sage_const_0 
    for lam, pts in sorted(lam2pair.items()):
        dv, fv = D(lam), F(lam)
        want = _sage_const_1  if len(pts) == _sage_const_2  else _sage_const_0      # 2 rational points above lam <=> split
        if len(pts) == _sage_const_1 :
            # either the fixed point of iota (2P=R, so D=0) or a genuine mismatch
            if dv != _sage_const_0 :
                bad += _sage_const_1 
                print("   !! lam=%s has ONE rational point but D(lam)=%s != 0" % (lam, dv))
        else:
            if dv == _sage_const_0 :
                bad += _sage_const_1 
                print("   !! lam=%s has TWO rational points but D(lam)=0" % lam)
    print("   lambda-values realised by rational points: %d  | anomalies: %d"
          % (len(lam2pair), bad))

    # now recompute the three quantities with the CORRECTED lambda map
    chisum = ZZ(_sage_const_0 )
    for lam in K:
        v = D(lam)*F(lam)
        if v != _sage_const_0 :
            chisum += _sage_const_1  if v.is_square() else -_sage_const_1 

    S_rat = ZZ(_sage_const_0 )
    seen = set()
    for Q in E.points():
        if Q.is_zero():
            continue
        Q2 = Rpt - Q
        if Q2.is_zero() or Q2 == Q:
            continue
        key = frozenset([tuple(Q), tuple(Q2)])
        if key in seen:
            continue
        seen.add(key)
        S_rat += _sage_const_1  if (Q[_sage_const_1 ]*Q2[_sage_const_1 ]).is_square() else -_sage_const_1 

    K2 = GF(p**_sage_const_2 , 'a')
    E2 = EllipticCurve(K2, [A, B])
    R2 = E2(Rpt[_sage_const_0 ], Rpt[_sage_const_1 ])
    S_conj = ZZ(_sage_const_0 )
    seen2 = set()
    n_conj = _sage_const_0 
    for P in E2.points():
        if P.is_zero():
            continue
        if P[_sage_const_0 ] in K and P[_sage_const_1 ] in K:
            continue
        Pc = E2(P[_sage_const_0 ]**p, P[_sage_const_1 ]**p)
        if P + Pc != R2:
            continue
        key = frozenset([tuple(P), tuple(Pc)])
        if key in seen2:
            continue
        seen2.add(key)
        n_conj += _sage_const_1 
        S_conj += _sage_const_1  if K(P[_sage_const_1 ]*Pc[_sage_const_1 ]).is_square() else -_sage_const_1 

    print("   chisum=%d   S_rat=%d (%d pairs)   S_conj=%d (%d pairs)   chisum-(S_rat-S_conj)=%d"
          % (chisum, S_rat, len(seen), S_conj, n_conj, chisum - (S_rat - S_conj)))
    # accounting: #F_p-lambdas = #split + #inert + #(rational roots of D)
    nsplit = len(seen)
    print("   accounting: p=%d  split=%d + inert=%d + ratrootsD=%d = %d"
          % (p, nsplit, n_conj, len(D.roots()), nsplit + n_conj + len(D.roots())))


print("--- ODD-n reference (should be clean) ---")
diagnose(_sage_const_43 , _sage_const_0 , _sage_const_7 , _sage_const_1 )
print("--- EVEN-n, supersingular j=1728 (the failing control) ---")
diagnose(_sage_const_43 , _sage_const_1 , _sage_const_0 , _sage_const_1 )
diagnose(_sage_const_43 , _sage_const_1 , _sage_const_0 , _sage_const_2 )
print("--- EVEN-n, ORDINARY generic j ---")
for (p, A, B) in [(_sage_const_43 , _sage_const_2 , _sage_const_3 ), (_sage_const_67 , _sage_const_1 , _sage_const_5 ), (_sage_const_79 , _sage_const_2 , _sage_const_5 )]:
    E = EllipticCurve(GF(p), [A, B])
    if E.order() % _sage_const_2  == _sage_const_0 :
        diagnose(p, A, B, _sage_const_1 )

